#include <stdio.h>
int maxSubArray(int nums[], int n) {
    int maxSum=nums[0], curSum=nums[0];
    for (int i=1; i<n; i++) {
        curSum = nums[i]>curSum+nums[i] ? nums[i] : curSum+nums[i];
        if (curSum>maxSum) maxSum=curSum;
    }
    return maxSum;
}
int main() {
    int a[]= {-2, 1, -3, 4, -1, 2, 1, -5, 4};
    printf("%d\n", maxSubArray(a, 9));
    return 0;
}

