#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int maxSubArray(vector<int>& nums) {
    int mx=nums[0], cur=nums[0];
    for (int i=1; i<(int)nums.size(); i++) {
        cur=max(nums[i], cur+nums[i]);
        mx=max(mx, cur);
    }
    return mx;
}
int main() {
    vector<int> a= {-2, 1, -3, 4, -1, 2, 1, -5, 4};
    cout<<maxSubArray(a)<<endl;
    return 0;
}
